PT={'opinar':'opinar','escuchar':'ouvir','discrepar':'discordar','argumentar':'argumentar','cambiar':'mudar','desviarse':'desviar-se','buscar':'procurar','proponer':'propor','escribir':'escrever','recordar':'lembrar','recorrer':'percorrer','explicar':'explicar','negociar':'negociar','priorizar':'priorizar','decidir':'decidir','mezclar':'misturar','medir':'medir','añadir':'adicionar','probar':'provar','esperar':'esperar','preguntar':'perguntar','aclarar':'esclarecer','avisar':'avisar','organizar':'organizar','llegar':'chegar','contar':'contar','reunirse':'reunir-se','invitar':'convidar','confirmar':'confirmar','combinar':'combinar','consultar':'consultar','encontrar':'encontrar','guardar':'guardar','planificar':'planejar','cuidar':'cuidar','justificar':'justificar'}

def enrich(e,p,prev):
 e=base.make(e,p,prev)
 # replace vocabulary distractors with real words from this episode; no placeholder options
 words=[x[0] for x in p['v']]
 for f in e['fr']:
  if f.get('k')=='pgsheet' and f.get('title')=='Palavras da cena':
   for i,c in enumerate(f['items']):
    c['opts']=[words[i],words[(i+1)%6],words[(i+2)%6]]
    c['a']=0
 # natural, contextual verb cards and quiz
 items=next(f for f in e['fr'] if f.get('k')=='verbs')['items']
 for i,(verb,pt) in enumerate([(x,PT.get(x,x)) for x in p['vb']]):
  it=items[i]; it['pt']=pt; it['f']=[['yo',p['s1'][i*2][1]],['ella',p['s1'][i*2+1][1]]]; it['ex']=[p['s1'][i*2][1],p['s1'][i*2][2]]; it['note']=f'Use **{verb}** para falar de {p["focus"]}.'
  it['v']=verb
 for f in e['fr']:
  if f.get('k')=='verbs':
   f['quiz']=[{'text':f'Escolha a forma usada na cena: {p["s1"][i*2][1]}','opts':[p['vb'][i],p['vb'][(i+1)%4],p['vb'][(i+2)%4]],'a':0,'why':f'**{p["vb"][i]}** é o verbo que completa a situação.'} for i in range(4)]
  if f.get('k')=='pgexp':
   for i,q in enumerate(f.get('quiz',[])):
    q['opts']=[p['ex'][i*2+1],p['ex'][(i+1)%4*2+1],p['ex'][(i+2)%4*2+1]]; q['a']=0
  if f.get('k')=='pgsheet' and f.get('title') in ('Complete as falas','Qual está certa?','Caça-sons'):
   for q in f.get('items',[]):
    opts=q.get('opts',[])
    q['opts']=[x for x in opts if x not in ('outra palavra','outra forma','outra opção')]
 # add source and coherent metadata
 e['a']['src']=p['work']; e['h']['src']=p['work']; e['p']=f'Hoje você aprende a {p["focus"]}, em uma situação inspirada por **{p["work"]}**.'
 return e

data=json.loads(PATH.read_text(encoding='utf-8')); by={e['n']:e for e in data}; prev=by[248]
for p in PLANS:
 by[p['n']]=enrich(by[p['n']],p,prev); prev=by[p['n']]
PATH.write_text(json.dumps([by[e['n']] for e in data],ensure_ascii=False,separators=(',',':')),encoding='utf-8')
print('wrote', [p['n'] for p in PLANS])
